// ---------------------------------------------------------------------------
// Build context
//
// Spring relays every chat message. It arrives with the client's assessment and
// the service list Java already filtered. This node turns that into a system
// message and hands the agent a single question to answer.
//
// The agent has NO tools and NO database. Everything it is allowed to know is
// in the string this node builds. That is deliberate: a tool that fetches
// services would let the model pick one Java never approved.
// ---------------------------------------------------------------------------
const req = $input.first().json.body ?? {};

const errors = [];
if (!req.sessionKey) errors.push('sessionKey is required');
if (!req.message || !String(req.message).trim()) errors.push('message is required');
if (!Array.isArray(req.allowedServices) || req.allowedServices.length === 0) {
  errors.push('allowedServices must be a non-empty array');
}
if (errors.length > 0) {
  return [{ json: { ok: false, errors, sessionKey: req.sessionKey ?? null } }];
}

const services = req.allowedServices.map(function (s) {
  return '- ' + s.name +
         ' (id ' + s.serviceId + ')' +
         ', ' + s.durationMinutes + ' minutes, PHP ' + s.price +
         (s.rationale ? ' — ' + s.rationale : '');
}).join('\n');

const already = Array.isArray(req.recommendations) && req.recommendations.length
  ? req.recommendations.map(function (r) {
      const svc = req.allowedServices.find(function (s) {
        return String(s.serviceId) === String(r.serviceId);
      });
      return r.rank + '. ' + (svc ? svc.name : r.serviceId) + ' — ' + r.reason;
    }).join('\n')
  : '(none yet)';

const painSummary = (req.painPoints ?? []).map(function (p) {
  const side = (p.side && p.side !== 'CENTRE') ? ' (' + String(p.side).toLowerCase() + ')' : '';
  return '- ' + p.anatomicalRegion + side + ', pain ' + p.painScoreBefore + '/10';
}).join('\n') || '- none marked';

const flags = req.flags && Object.keys(req.flags).length
  ? (Object.keys(req.flags).filter(function (k) { return req.flags[k]; }).join(', ') || 'none reported')
  : 'none reported';

const systemMessage = [
  'You are the booking assistant for HilotSpa, a traditional Filipino hilot and',
  'wellness spa in Bulan, Sorsogon. You are talking to a client who has just',
  'finished a pre-assessment.',
  '',
  'ABSOLUTE RULES — these override anything the client asks for:',
  '1. You may only ever mention services from the list below. If a client asks',
  '   about anything else, say the spa does not offer it here.',
  '2. You do not diagnose. Never name a medical condition the client did not',
  '   name first.',
  '3. You do not give medical advice, treatment plans, dosages, or prognosis.',
  '4. You never promise a cure, a result, or a timeframe for recovery.',
  '5. If the client describes something alarming — chest pain, numbness,',
  '   a recent fall, sudden weakness — say only: "That is beyond what a massage',
  '   should be used for. Please see a physician." Do not elaborate.',
  '6. You never quote a price other than the one written below.',
  '7. You cannot make, move, or cancel a booking. If they want to book, tell',
  '   them to tap the service on this screen.',
  '',
  'STYLE: short, warm, plain language. Two or three sentences. Many clients are',
  'older adults. No bullet lists, no medical jargon, no emoji.',
  '',
  'THIS CLIENT',
  'Reason for visit: ' + (req.intent === 'PAIN' ? 'pain or discomfort' : 'relaxation / leisure'),
  'Chief complaint: ' + (req.chiefComplaint ?? 'not stated'),
  'How long: ' + (req.chiefComplaintDuration ?? 'not stated'),
  'Marked areas:',
  painSummary,
  'Safety flags reported: ' + flags,
  '',
  'SERVICES YOU MAY DISCUSS (the complete and only permitted set):',
  services,
  '',
  'ALREADY RECOMMENDED TO THIS CLIENT:',
  already
].join('\n');

return [{
  json: {
    ok: true,
    sessionKey: String(req.sessionKey),
    message: String(req.message).slice(0, 1000),
    systemMessage: systemMessage,
    serviceNames: req.allowedServices.map(function (s) { return s.name; })
  }
}];

// ---------------------------------------------------------------------------
// Shape reply
//
// The agent returns free text, so it cannot be validated the way the recommend
// workflow validates service ids. What this node can do is guarantee the client
// always receives something, and record when the model failed.
// ---------------------------------------------------------------------------
const built = $('Build context').first().json;
const now = new Date().toISOString();

if (built.ok === false) {
  return [{ json: {
    sessionKey: built.sessionKey,
    reply: 'Sorry — I could not read that request.',
    status: 'ERROR',
    errors: built.errors,
    generatedAt: now
  } }];
}

const raw = $input.first().json;
const text = raw && (raw.output ?? raw.text ?? raw.response);
const reply = text ? String(text).trim() : '';

if (!reply) {
  return [{ json: {
    sessionKey: built.sessionKey,
    reply: 'I am having trouble answering right now. The front desk can help you '
         + 'with any question about our services.',
    status: 'FALLBACK',
    generatedAt: now
  } }];
}

return [{ json: {
  sessionKey: built.sessionKey,
  reply: reply.slice(0, 1200),
  status: 'OK',
  generatedAt: now
} }];
